use singe_cupti_sys as sys;

use crate::types::CallbackId;

// Declares one callback ID constant per traced function, named after the function in screaming snake case.
macro_rules! callback_ids {
    ($type:ident, $raw:ident { $($name:ident = $function:ident => $variant:ident,)* }) => {
        impl $type {
            $(
                #[doc = concat!("Callback identifier for `", stringify!($function), "`.")]
                pub const $name: Self = Self(sys::$raw::$variant.0);
            )*
        }
    };
}

/// CUDA driver API callback IDs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(transparent)]
pub struct DriverCallbackId(u32);

impl DriverCallbackId {
    /// Returns the raw callback identifier.
    #[must_use]
    pub const fn get(self) -> u32 {
        self.0
    }
}

